import * as React from "react";
import styles from "./HodViewScorecardDetail.module.scss";
import CommentView from "./ScorecardCommentView";
import ScorecardQuestionsView from "./ScorecardQuestionsView";


const HodViewScorecardDetail: React.FC<any> = ({ 
  stateValue, 
  candidateData, 
  questionnaire, 
  comments, 
  navigateBack, 
  isLoading 
}) => {
  const [activeSideTab, setActiveSideTab] = React.useState("Candidate Info");

  // DYNAMIC CONFIG: Add any field here and it will automatically appear in the UI
  const candidateFields = [
    { label: "Candidate Name", value: candidateData?.CandidateName },
    { label: "Nationality", value: candidateData?.Nationality },
    { label: "Total Experience", value: candidateData?.TotalExperience },
    { label: "Current Position", value: candidateData?.CurrentPosition },
    { label: "Notice Period", value: candidateData?.NoticePeriod },
    { label: "Expected Salary", value: candidateData?.ExpectedSalary },
    { label: "Job Code", value: candidateData?.JobCode },
    { label: "Department", value: stateValue?.Department }
  ];

  React.useEffect(() => {
    // Tamil request: intha values list la irunthu varuth appa add to console
    console.log("HodViewScorecardDetail candidateFields:", candidateFields);
  }, [candidateFields]);

  const menuItems = ["Candidate Info", "Interview Scorecard", "Justification", "Q&A"];

  return (
 
      <div className={styles.mainLayout}>
        
        {/* LEFT SIDEBAR NAVIGATION */}
        <aside className={styles.sidebar}>
          <div className={styles.sidebarHeader}>
            <h3>{candidateData?.JobCode || "SCORECARD"}</h3>
            <p>Review Management</p>
          </div>
          <nav className={styles.navGroup}>
            {menuItems.map((item) => (
              <div
                key={item}
                className={`${styles.navItem} ${activeSideTab === item ? styles.active : ""}`}
                onClick={() => setActiveSideTab(item)}
              >
                {item}
              </div>
            ))}
          </nav>
          <button className={styles.backButton} onClick={navigateBack}>
            ← Back to List
          </button>
        </aside>

        {/* RIGHT CONTENT AREA */}
        <main className={styles.contentCard}>
          <div className={styles.contentHeader}>
            <h2>{activeSideTab}</h2>
            <div className={styles.statusPill}>{stateValue?.Status || "Under Review"}</div>
          </div>

          <div className={styles.scrollContent}>
            {activeSideTab === "Candidate Info" && (
              <div className={styles.dynamicGrid}>
                {candidateFields.map((field, index) => (
                  <div key={index} className={styles.inputBox}>
                    <label>{field.label}</label>
                    <input type="text" value={field.value || "N/A"} readOnly />
                  </div>
                ))}
              </div>
            )}

            {activeSideTab === "Justification" && (
              <CommentView 
                level1={comments?.level1 || []} 
                level2={comments?.level2 || []} 
                onClose={() => setActiveSideTab("Candidate Info")} 
              />
            )}

            {activeSideTab === "Q&A" && (
              <ScorecardQuestionsView 
                questionnaire={questionnaire || []} 
                onClose={() => setActiveSideTab("Candidate Info")} 
              />
            )}
            
            {activeSideTab === "Interview Scorecard" && (
              <div className={styles.placeholder}>
                {/* Scorecard table logic goes here */}
                <p>Scorecard Table Content Loading...</p>
              </div>
            )}
          </div>
        </main>
      </div>
  );
};

export default HodViewScorecardDetail;